import base64
from PIL import Image
from io import BytesIO

# 데이터베이스에서 가져온 데이터 예시 (Base64 문자열)
base64_data = ""

try:
    # Base64 디코딩
    image_data = base64.b64decode(base64_data)
    
    # 디코딩된 데이터를 이미지로 변환하여 확인
    image = Image.open(BytesIO(image_data))
    image.show()
    print("Base64로 인코딩된 이미지입니다.")
except Exception as e:
    print("Base64로 인코딩된 이미지가 아닙니다. 오류:", e)
